using FolderVerse;using Microsoft.Xna.Framework;using Microsoft.Xna.Framework.Graphics;using Microsoft.Xna.Framework.Input;using System.Reflection;
using var game=new PerformanceUi(args[0]);game.Run();
sealed class PerformanceUi(string output):Game1{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;WorldSetup w=null!;SpriteBatch batch=null!;int frame;
 object Get(string n)=>typeof(Game1).GetField(n,F)!.GetValue(this)!;void Set(string n,object v)=>typeof(Game1).GetField(n,F)!.SetValue(this,v);object Call(string n,params object[] a)=>typeof(Game1).GetMethod(n,F)!.Invoke(this,a)!;
 void Check(bool ok,string m){if(!ok)throw new Exception(m);Console.WriteLine("PASS "+m);} protected override void LoadContent(){Window.Position=new(-3000,-3000);AppContext.SetData("APP_CONTEXT_BASE_DIRECTORY",Environment.GetEnvironmentVariable("GAME_RUNTIME"));w=new(){EquipmentMode=RobotEquipmentMode.Materials};w.SetParticipantCounts(1,1);w.SetWorld(1);w.SetCast(2);w.SetPlacement(3);w.Relations.Reset();w.SelectPlayer(0);w.Relations.Leader=0;w.Robots.Initialize(w.Nodes.All.Length,w.ActiveCount);w.Robots.ConfigureFactories(w);w.Salvage.Reset();w.Salvage.EnableExpeditions(w);foreach(var n in w.Nodes.All)n.Owner=0;int h=w.Nodes.All.First(n=>n.Functional).Id;w.ConquerorLocations[0]=w.Nodes.All[h].Cell;w.ConquerorPoints[0]=w.Nodes.All[h].Center;
 foreach(var material in Enum.GetValues<RobotMaterial>()){var robot=w.Robots.Create(0,RobotParts.Complete,RobotRole.Captain) with{HeadMaterial=material,BodyMaterial=(RobotMaterial)(((int)material+1)%9),LegsMaterial=material};w.Robots.Nodes[h].Add(robot);var good=w.Robots.Create(1,RobotParts.Complete) with{HeadMaterial=material,BodyMaterial=material,LegsMaterial=material,IntegratedParts=(int)material%2==0?RobotParts.Head|RobotParts.Body:0};w.Salvage.Items.Add(new(1000+(int)material,h,good));}
 Set("_setup",w);batch=new(GraphicsDevice);var pixel=new Texture2D(GraphicsDevice,1,1);pixel.SetData(new[]{Color.White});Set("_spriteBatch",batch);Set("_pixel",pixel);Content.RootDirectory=Path.Combine(Environment.GetEnvironmentVariable("OLD_RUNTIME")!,"Content");Set("_portraitRenderer",new PortraitRenderer(Content));var fonts=new Microsoft.Xna.Framework.Content.ContentManager(Services,Path.Combine(Environment.GetEnvironmentVariable("PROBE_FONT")!,"Content"));var font=fonts.Load<SpriteFont>("UiFont");Set("_font",font);Set("_ui",Activator.CreateInstance(typeof(Game1).GetField("_ui",F)!.FieldType,batch,pixel,font)!);Set("_conquestAudioUnavailable",true);Set("_screen",Enum.Parse(Get("_screen").GetType(),"WorldStatus"));Call("BeginConquestOverview");CheckInputs();} void CheckInputs(){
 var type=Get("_screen").GetType();Set("_screen",Enum.Parse(type,"Title"));Set("_titleMenuOpen",true);Set("_pointer",new Point(950,817));Call("TitleStartMenuInput",true,false,false,new KeyboardState(),true);Check((bool)Get("_titleSystemMenuOpen"),"title start menu opens actual system menu");
 Set("_pointer",new Point(900,515));Call("PerformanceUiInput",new MouseState(0,0,0,ButtonState.Pressed,ButtonState.Released,ButtonState.Released,ButtonState.Released,ButtonState.Released),new KeyboardState(),true);Check((bool)Get("_performanceVisible")&&!(bool)Get("_titleSystemMenuOpen"),"title system menu enables overlay");
 foreach(var screen in Enum.GetValues(type)){Set("_screen",screen);Set("_performanceVisible",true);Set("_pointer",new Point(1900,20));bool consumed=(bool)Call("PerformanceUiInput",new MouseState(0,0,0,ButtonState.Pressed,ButtonState.Released,ButtonState.Released,ButtonState.Released,ButtonState.Released),new KeyboardState(),true);if(!consumed||(bool)Get("_performanceVisible"))throw new Exception("close failed in "+screen);}
 Console.WriteLine("PASS close consumes input in every screen enum");Set("_screen",Enum.Parse(type,"WorldStatus"));Set("_statusMenuOpen",true);Call("StatusMenuClick",new Point(1500,595));Check((bool)Get("_performanceVisible"),"in-game system menu enables overlay");
 var metric=(FramePerformance)Get("_framePerformance");double origin=System.Diagnostics.Stopwatch.GetTimestamp()/(double)System.Diagnostics.Stopwatch.Frequency-1;for(int i=0;i<=60;i++){metric.Update(2);metric.Draw(origin+i/60d,12,9);}
 }
 protected override void Update(GameTime t){}
 protected override void Draw(GameTime t){
 using var image=new RenderTarget2D(GraphicsDevice,1920,1080);GraphicsDevice.SetRenderTarget(image);GraphicsDevice.Clear(Color.DarkSlateBlue);
 if(frame==0){Set("_conquestStage",4);Set("_conquestAge",0d);base.Draw(t);Check(WorldPreview.DrawCpuMilliseconds>0,"globe CPU submission is measured");}else{Set("_screen",Enum.Parse(Get("_screen").GetType(),"Title"));Set("_titleSystemMenuOpen",true);Call("DrawPerformanceUi");}
 var pixels=new Color[1920*1080];image.GetData(pixels);Check(pixels[20*1920+280].R<80,"black top band overlays scene "+frame);GraphicsDevice.SetRenderTarget(null);using(var file=File.Create(Path.Combine(output,$"performance-{frame}.png")))image.SaveAsPng(file,1920,1080);
 if(++frame==2){Console.WriteLine("PASS real early-return conquest frame and title system menu render");Exit();}
